<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #080b12;
      --panel: #111827;
      --panel-soft: #182234;
      --text: #eef4ff;
      --muted: #9aa8bd;
      --danger: #ff4d67;
      --danger-dark: #d72e49;
      --border: rgba(255, 255, 255, 0.12);
      --shadow: 0 28px 80px rgba(0, 0, 0, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 32px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at 20% 10%, rgba(80, 120, 255, 0.18), transparent 30%),
        radial-gradient(circle at 80% 15%, rgba(255, 77, 103, 0.14), transparent 26%),
        linear-gradient(135deg, #070a11 0%, var(--bg) 52%, #0e1420 100%);
      color: var(--text);
    }

    .preview-card {
      width: min(100%, 760px);
      padding: 24px;
      border: 1px solid var(--border);
      border-radius: 28px;
      background: rgba(17, 24, 39, 0.78);
      box-shadow: var(--shadow);
      backdrop-filter: blur(22px);
    }

    .image-wrap {
      overflow: hidden;
      border-radius: 22px;
      border: 1px solid rgba(255, 255, 255, 0.1);
      background: #0d1320;
    }

    .image-wrap img {
      display: block;
      width: 100%;
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .preview-details {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      margin-top: 22px;
    }

    h1 {
      margin: 0 0 6px;
      font-size: clamp(1.5rem, 3vw, 2.15rem);
      line-height: 1.1;
    }

    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    button {
      border: 0;
      border-radius: 999px;
      font: inherit;
      font-weight: 750;
      cursor: pointer;
      transition: transform 160ms ease, background 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(125, 162, 255, 0.45);
      outline-offset: 3px;
    }

    .trigger {
      flex: 0 0 auto;
      padding: 13px 20px;
      color: #fff;
      background: linear-gradient(135deg, var(--danger), var(--danger-dark));
      box-shadow: 0 14px 32px rgba(255, 77, 103, 0.28);
    }

    .trigger:hover {
      box-shadow: 0 18px 38px rgba(255, 77, 103, 0.34);
    }

    .modal {
      position: fixed;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      background: rgba(3, 6, 13, 0.72);
      opacity: 0;
      pointer-events: none;
      transition: opacity 180ms ease;
    }

    .modal.is-open {
      opacity: 1;
      pointer-events: auto;
    }

    .modal-card {
      width: min(100%, 440px);
      padding: 28px;
      border: 1px solid var(--border);
      border-radius: 24px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.02)),
        var(--panel);
      box-shadow: var(--shadow);
      transform: translateY(12px) scale(0.98);
      transition: transform 180ms ease;
    }

    .modal.is-open .modal-card {
      transform: translateY(0) scale(1);
    }

    .warning-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      margin-bottom: 18px;
      border-radius: 18px;
      color: #ffd8df;
      background: rgba(255, 77, 103, 0.16);
      box-shadow: inset 0 0 0 1px rgba(255, 77, 103, 0.22);
      font-size: 1.7rem;
    }

    .modal-card h2 {
      margin: 0 0 10px;
      font-size: 1.55rem;
      line-height: 1.2;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 26px;
    }

    .secondary,
    .danger {
      padding: 12px 18px;
    }

    .secondary {
      color: var(--text);
      border: 1px solid var(--border);
      background: var(--panel-soft);
    }

    .secondary:hover {
      border-color: rgba(255, 255, 255, 0.22);
      background: #202b3d;
    }

    .danger {
      color: #fff;
      background: linear-gradient(135deg, var(--danger), var(--danger-dark));
    }

    @media (max-width: 620px) {
      body {
        padding: 18px;
      }

      .preview-card {
        padding: 16px;
        border-radius: 22px;
      }

      .preview-details,
      .modal-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .trigger,
      .secondary,
      .danger {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="preview-card" aria-labelledby="page-title">
    <div class="image-wrap">
      <img
        src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80"
        alt="A quiet lakeside cabin surrounded by trees at golden hour"
      >
    </div>

    <div class="preview-details">
      <div>
        <h1 id="page-title">Lakeside Retreat</h1>
        <p>Saved to your library · 4.8 MB · JPG</p>
      </div>
      <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
        Delete image
      </button>
    </div>
  </main>

  <div class="modal" id="delete-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-description" hidden>
    <section class="modal-card">
      <div class="warning-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will permanently remove “Lakeside Retreat” from your library. This action cannot be undone.
      </p>
      <div class="modal-actions">
        <button class="secondary" type="button" data-close>Cancel</button>
        <button class="danger" type="button" data-confirm>Delete permanently</button>
      </div>
    </section>
  </div>

  <script>
    const trigger = document.querySelector('.trigger');
    const modal = document.querySelector('#delete-dialog');
    const closeButton = modal.querySelector('[data-close]');
    const confirmButton = modal.querySelector('[data-confirm]');

    function openDialog() {
      modal.hidden = false;
      requestAnimationFrame(() => {
        modal.classList.add('is-open');
        closeButton.focus();
      });
    }

    function closeDialog() {
      modal.classList.remove('is-open');
      trigger.focus();
      modal.addEventListener('transitionend', () => {
        if (!modal.classList.contains('is-open')) {
          modal.hidden = true;
        }
      }, { once: true });
    }

    trigger.addEventListener('click', openDialog);
    closeButton.addEventListener('click', closeDialog);
    confirmButton.addEventListener('click', closeDialog);

    modal.addEventListener('click', (event) => {
      if (event.target === modal) {
        closeDialog();
      }
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && !modal.hidden) {
        closeDialog();
      }
    });
  </script>
</body>
</html>
