      </p>
      <div class="modal-actions">
        <button class="secondary" type="button" data-close>Cancel</button>
        <button class="danger" type="button" data-confirm>Delete permanently</button>
      </div>
    </section>
  </div>

  <script>
    const trigger = document.querySelector('.trigger');
    const modal = document.querySelector('#delete-dialog');
    const closeButton = modal.querySelector('[data-close]');
    const confirmButton = modal.querySelector('[data-confirm]');

    function openDialog() {
      modal.hidden = false;
      requestAnimationFrame(() => {
        modal.classList.add('is-open');
        closeButton.focus();
      });
    }

    function closeDialog() {
      modal.classList.remove('is-open');
      trigger.focus();
      modal.addEventListener('transitionend', () => {
        if (!modal.classList.contains('is-open')) {
          modal.hidden = true;
        }
      }, { once: true });
    }

    trigger.addEventListener('click', openDialog);
    closeButton.addEventListener('click', closeDialog);
    confirmButton.addEventListener('click', closeDialog);

    modal.addEventListener('click', (event) => {
      if (event.target === modal) {
        closeDialog();
      }
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && !modal.hidden) {
        closeDialog();
      }
    });
  </script>
